/**
 * Product Routes — CRUD + search/filter/paginate.
 * Generated by BackendForge
 */
const express = require('express');
const router = express.Router();
const productController = require('../controllers/product.controller');
const { authenticate, authorize, optionalAuth } = require('../middleware/auth.middleware');
const { validate, schemas } = require('../middleware/validator.middleware');

// Public routes
router.get('/', optionalAuth, productController.listProducts);
router.get('/:id', optionalAuth, productController.getProduct);

// Admin-only routes
router.post('/', authenticate, authorize('admin', 'superadmin'), validate(schemas.createProduct), productController.createProduct);
router.put('/:id', authenticate, authorize('admin', 'superadmin'), productController.updateProduct);
router.delete('/:id', authenticate, authorize('admin', 'superadmin'), productController.deleteProduct);

module.exports = router;
